from collections import Counter as C2
def solve(di):
    h=len(di); w=len(di[0])
    cnt=C2(x for r in di for x in r); bgc=cnt.most_common(1)[0][0]
    best=None
    for v in sorted(cnt, key=lambda v:(-(cnt[v]*v),)):
        cl=[(r,c) for r in range(h) for c in range(w) if di[r][c]==v]
        rs=[r for r,_ in cl]; cs=[c for _,c in cl]
        area=(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
        fill=len(cl)==area and len(cl)>1
        # core = large solid rectangle
        if fill and (best is None or len(cl)>len(best[1])):
            best=(cl,len(cl))
    cores=set(best[0]); cr=(min(r for r,_ in cores)+max(r for r,_ in cores))/2
    cc=(min(c for _,c in cores)+max(c for _,c in cores))/2
    out=[row[:] for row in di]
    for r in range(h):
        for c in range(w):
            if di[r][c]!=bgc and (r,c) not in cores:
                col=di[r][c]
                for rr in {r,int(round(2*cr-r))}:
                    for c2 in {c,int(round(2*cc-c))}:
                        if (rr,c2) not in cores and di[rr][c2]==bgc:
                            out[rr][c2]=col
    return out
